import logging
import traceback
from taf.ue.plugin.mtk.ue import Apollo, Petrus, Oppo, Lepin, Figeac, Dujac, Caymus, Bollinger
from taf.ue.plugin.mtk.exceptions import UeTypeNotSupported
from taf.ue.plugin.mtk.mace import MTKRPCProxy
from taf.ue.plugin.mtk.injecter import Injecter
from taf.ue.plugin.mtk.catch_exceptions import catch_mtkue_interface_exception
from ute_ue.lteue import LteUe
from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from ute_common_abstract_core.aliases_registry import aliases_registry
from ute_common_abstract_core.exceptions import UnknownAlias
from ute_common_abstract_core.exceptions import WrongAlias
from ute_common_abstract_core.network_elem_identification import UeIdentification
from ute_ue.utils.vm_utils import get_vm_test_logs_dir


CONSTRUCTOR_PARAMETERS = 'CONSTRUCTOR_PARAMETERS'


class MediaTekUe(LteUe, Injecter):

    _SUPPORTED_UES = [Apollo, Petrus, Oppo, Lepin, Figeac, Dujac, Caymus, Bollinger]

    def __init__(self, configuration, **kwargs):
        """
        MediaTek Ue initialization.
        :param configuration:
        :return:
        """
        name = kwargs.get("name", "MTK_UE_1")
        super(MediaTekUe, self).__init__(name, configuration)

        logging.info('Create MediaTekUe start...')

        self._config = configuration
        self._config.setdefault('server_python')
        self._config.setdefault('com_port', 'auto')
        ue_pc_ip = self._config['ue_pc_ip']
        ue_pc_port = self._config['pyro_port']

        self.ne_id = UeIdentification(identifiers=[('mediatek', (ue_pc_ip, ue_pc_port))],
                                      network_elem_type='UE',
                                      specific_for_tool='mediatek')

        self._mtk_rpc_proxy = None
        self._setup_mtk_rpc_proxy(self._config)
        self._ue = None
        self._elg_enabled = False
        self._prepare_ue()

    def _setup_mtk_rpc_proxy(self, config):
        self._mtk_rpc_proxy = MTKRPCProxy(config)
        self._mtk_rpc_proxy.setup()

    @catch_mtkue_interface_exception
    def _prepare_ue(self):
        try:
            self._ue = self._create_ue()
            self._ue.pre_attach()
            self._ue.refresh_mtk_log()
        except Exception as e:
            logging.error("prepare ue failure: {} {}".format(str(e), str(traceback.print_exc())))
            raise

    @catch_mtkue_interface_exception
    def reboot(self):
        self._ue.reboot()

        self._ue.pre_attach()
        self._ue.refresh_mtk_log()

    @catch_mtkue_interface_exception
    def change_deployment_mode(self, deployment_mode):
        if self.get_deployment_mode().upper() == deployment_mode.upper():
            return

        self._ue.change_deployment_mode(deployment_mode)

        self._ue.pre_attach()
        self._ue.refresh_mtk_log()

    @catch_mtkue_interface_exception
    def overheating(self, oh_op=0, cc_dl=None, cc_ul=None,
                    bw_fr1_dl=None, bw_fr1_ul=None, bw_fr2_dl=None, bw_fr2_ul=None,
                    mimo_fr1_dl=None, mimo_fr2_dl=None, mimo_fr1_ul=None, mimo_fr2_ul=None):
        self._ue.overheating(oh_op, cc_dl, cc_ul, bw_fr1_dl, bw_fr1_ul, bw_fr2_dl, bw_fr2_ul,
                             mimo_fr1_dl, mimo_fr2_dl, mimo_fr1_ul, mimo_fr2_ul)

    def enable_edrx_setting(self, enable=True):
        if not isinstance(enable, bool):
            enable = str(enable).lower() in ['true', '1', 't', 'y', 'yes']
        self._ue.enable_edrx_setting(enable)

    def set_nr_edrx(self, circle_length_duration, extended_paging_time_window, unsolicited_result_code=True):
        self._ue.set_nr_edrx(circle_length_duration, extended_paging_time_window, unsolicited_result_code)

    @catch_mtkue_interface_exception
    def lock_cell(self, network_technology, arfcn, pci=None):
        self._ue.lock_cell(network_technology, arfcn, pci)

    @catch_mtkue_interface_exception
    def unlock_cell(self, network_technology, arfcn, pci=None):
        self._ue.unlock_cell(network_technology, arfcn, pci)

    def _create_ue(self):
        ue_class = self._search_ue_class()
        ue = ue_class(self._config, self._mtk_rpc_proxy.mace_proxy)
        ue.setup()
        return ue

    def _search_ue_class(self):
        mtk_hw_version = self._get_ue_hw_version()
        for ue_class in self._SUPPORTED_UES:
            if isinstance(ue_class.HW_VERSION, (list, tuple)) and mtk_hw_version in ue_class.HW_VERSION:
                return ue_class
            elif ue_class.HW_VERSION == mtk_hw_version:
                return ue_class
        raise UeTypeNotSupported(mtk_hw_version)

    def _get_ue_hw_version(self):
        platform_info = self._mtk_rpc_proxy.get_platform_info()
        logging.info("UE platform info: {}".format(platform_info))
        hw_version = platform_info["MtkHW"].split("_")[0]
        if "OPPO" in platform_info["Project"]:
            hw_version = "OPPO"
        return hw_version

    @property
    def ue_ip(self):
        return self._ue.ip

    def iperf_client_only(self):
        return isinstance(self._ue, Caymus)

    def shutdown(self):
        self.logger.debug('Shutdown MediaTek UE.')
        try:
            self._save_remote_files(get_vm_test_logs_dir())
            return self._ue.teardown()
        except Exception as e:
            self.logger.error(e)

    def get_deployment_mode(self):
        """
        Detect deployment mode
        :return: deployment mode
        :rtype: str
        """
        return self._ue.deployment_mode

    def enable_vonr_capability(self):
        self._ue.enable_vonr_capability()

    def power_off_sim(self):
        self._ue.power_off_sim()

    def power_on_sim(self):
        self._ue.power_on_sim()

    @catch_mtkue_interface_exception
    def attach(self, timeout=3):
        """
        Perform attach on UE.

        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If attach failed
        """
        logging.info('Attach start...')
        try:
            self.logger.debug("Attach via: AT Command alias={}".format(self.name))
            self._ue.attach(timeout)
        except Exception as err:
            self.logger.error('{!r}'.format(err))
            self.shutdown()
            raise
        else:
            self.logger.info('Attach succeeded')

    @catch_mtkue_interface_exception
    def register(self, timeout=3):
        return self._ue.register(timeout)

    def enable_builtin_apn_check(self, enable=True):
        self._ue.enable_builtin_apn_check(enable)

    def _create_voice_call(self, name, definition):
        return self._ue.create_voice_call(name=name, ue_name=self.name, definition=definition)

    @catch_mtkue_interface_exception
    def detach(self, timeout=-1):
        """
        Perform detach on UE.

        No action if UE is already detached.

        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If detach failed
        """
        logging.info('Detach start.')
        try:
            self.logger.debug("Detach via: AT Command alias={}".format(self.name))
            self._ue.detach()
        except Exception as err:
            self.logger.error('{!r}'.format(err))
            self.shutdown()
            raise
        else:
            self.logger.info('detach succeeded')

    @catch_mtkue_interface_exception
    def create_default_pdn(self):
        return self._ue.create_default_pdn()

    def _create_data_transfer(self, name, dt_definition):
        """
        Abstract method for creating data transfer of specific type.

        :param name: name to be assigned to starting transfer. You must use it later on to reference given transfer.
        :param dt_definition: object of DataTransferDefinition that encapsulates all needed parameters.
        :return: data_transfer - object derivered from prisma_data_transfer class
        """
        appserver, iperf_port = self._get_specified_appserver_and_iperf_port(dt_definition)
        return self._ue.create_data_transfer(name, dt_definition, self, appserver, iperf_port)

    def get_data_transfer_raw_data(self, dt_name, output_file=None):
        """Get all raw statistics of data transfer final result"""
        data_transfer = self._get_dt(dt_name)
        stats = data_transfer.get_data_transfer_raw_data(output_file)
        return stats

    def _get_dt(self, dt_name):
        """
        Find data transfer from dt aliases registry or raises exception.

        :param dt_name: alias of data transfer to find
        :return: dt object if found
        """
        if dt_name not in aliases_registry():
            expected_preceding_call = "Start Data Transfer  {} ...".format(dt_name)
            how_to_fix_info = "  you should precede it with starting data transfer with given alias '{}'".format(expected_preceding_call)
            self.logger.error("UnknownAlias({})".format(how_to_fix_info))
            raise UnknownAlias(how_to_fix_info)
        dt = aliases_registry()[dt_name]
        # aliases registry holds objects of different type, check if alias points to data transfer
        if not isinstance(dt, LteDataTransfer):
            why_wrong_info = "  should be alias of LteDataTransfer object but it points to '{}' object".format(dt.__class__.__name__)
            expected_preceding_call = "Start Data Transfer  DT_alias  ..."
            how_to_fix_info = "  you should use DT_alias given at '{}'".format(expected_preceding_call)
            err_msg = why_wrong_info + "\n" + how_to_fix_info
            self.logger.error("WrongAlias({})".format(err_msg))
            raise WrongAlias(err_msg)
        return dt

    @staticmethod
    def _get_specified_appserver_and_iperf_port(dt_definition):
        appserver = dt_definition.protocol_details.get("appserver", None)
        iperf_port = dt_definition.protocol_details.get("port", None)
        return appserver, iperf_port

    @catch_mtkue_interface_exception
    def connect_additional_pdn(self, pdn):
        """
        Establish additional default bearer.

        :param str pdn: PDN logical name (what type of network we want: internet, mms, ...)
        :return: UE ip from additional PDN
        :raises: :py:class:`taf.ue.plugin.mtk.exceptions.CreateAdditionalPduSessionFailure`:
        If connecting given PDN failed
        """
        return self._ue.connect_additional_pdn(pdn)

    @catch_mtkue_interface_exception
    def disconnect_additional_pdn(self, pdn):
        """
        Release additional default bearer.

        :param str pdn: PDN logical name (what type of network we want: internet, mms, ...)
        :return: None
        """
        self._ue.disconnect_additional_pdn(pdn)

    def switch_to_pdu_session(self, pdn_name):
        self._ue.switch_to_pdu_session(pdn_name)

    def get_ue_info(self):
        """
        get ue info.
        :return: dict contain ue ip info
        """
        return self._ue.get_ue_info()

    def get_ue_config(self):
        return self._config

    def get_rpc_proxy(self):
        if self._mtk_rpc_proxy:
            return self._mtk_rpc_proxy.mace_proxy
        return None

    def get_mtk_rpc(self):
        if self._mtk_rpc_proxy:
            return self._mtk_rpc_proxy.mtk_rpc
        return None

    def enable_elg_logging(self, enable=True):
        self._elg_enabled = enable

    def is_elg_enabled(self):
        return self._elg_enabled

    def _save_remote_files(self, target_dir):
        self.logger.debug('downloading remote logs start...')
        try:
            rpc = self.get_mtk_rpc()
            if rpc.workspace.is_accessable:
                rpc.workspace.collect_remote_files(rpc.workspace.log_dir, target_dir)
            else:
                rpc.workspace.setup()
                rpc.workspace.collect_remote_files(rpc.workspace.log_dir, target_dir)
                rpc.workspace.teardown()
            self.logger.debug('downloading remote logs done')
        except Exception as e:
            self.logger.warning("save remote files failed for {}, \r\n traceback is {}".
                                format(e, str(traceback.print_exc())))
